import org.springframework.stereotype.Service;
import org.springframework.stereotype.Repository;

@Service // singleton by default
public class OrderService {
    private final OrderRepository repository; // injected once

    public OrderService(OrderRepository repository) {
        this.repository = repository; // constructor runs once
        System.out.println("OrderService created: " + this);
    }

    public void placeOrder(Long userId, String item) {
        // called by multiple threads concurrently
        var order = new Order(userId, item); // local variable, thread-safe
        repository.save(order);
    }
}

@Repository // also singleton
public class OrderRepository {
    // no mutable instance state, thread-safe
    public void save(Order order) {
        // save to database
    }
}

record Order(Long userId, String item) {}
