import org.springframework.beans.factory.annotation.Lookup;
import org.springframework.context.annotation.Scope;
import org.springframework.stereotype.Component;
import org.springframework.stereotype.Service;
import java.util.UUID;

@Component
@Scope("prototype")
class RequestProcessor {
    private final String requestId = UUID.randomUUID().toString();
    public String process(String data) {
        return "Request " + requestId + " processed: " + data;
    }
}

@Service
abstract class OrderService {
    public String handleOrder(String order) {
        return createProcessor().process(order); // a fresh instance each call
    }

    @Lookup // Spring overrides this to return a new prototype every call
    protected abstract RequestProcessor createProcessor();
}
```
